function fmtTonys(f,spec,menu,poster){
  return fmtFaces([
`<div style="position: relative; width: 816px; height: 1056px; overflow: hidden; background: #18223f"><img src="assets/era/tonys/light-front-c46526.webp" alt="" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px; opacity: 1"><img src="assets/era/_shared/paper-grain.webp" alt="" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px; opacity: 0.16"><div style="position: absolute; left: 40px; top: 58px; width: 736px;"><div style="font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.22em; color: #f0b04a; text-transform: uppercase; line-height: 22px; text-align: center;">Ristorante italiano, supper till late</div></div><div style="position: absolute; left: 40px; top: 78px; width: 736px;"><div style="font-family: 'Corben', serif; font-weight: 700; font-size: 84px; line-height: 84px; color: #ffd98a; text-align: center; letter-spacing: 0.02em; text-shadow: 0 0 18px rgba(240,176,74,0.45)">Tony's</div></div><div style="position: absolute; left: 40px; top: 184px; width: 736px;"><div style="font-family: 'Crimson Pro', serif; font-style: italic; font-size: 21px; line-height: 1.2; color: #f6ecd4; text-align: center">Spaghetti every night. The best table is out back.</div></div><div style="position: absolute; left: 51px; top: 221px; width: 714px; height: 370px; border: 2px solid #f0b04a; box-sizing: border-box"></div><img src="assets/era/tonys/still-spaghetti-2ac07d.webp" alt="One strand of spaghetti shared by candlelight behind Tony's" style="position: absolute; left: 56px; top: 226px; width: 704px; height: 360px; box-shadow: 0 8px 22px rgba(0,0,0,0.5)"><div style="position: absolute; left: 56px; top: 598px; width: 704px;"><div style="display: flex; justify-content: space-between; font-family: 'Crimson Pro', serif; font-style: italic; font-size: 19px; color: #b9bfd3"><span>Out back, by the barrels. One plate, one candle.</span><span style="color: #f0b04a">Regulars at the back door eat free</span></div></div><div style="position: absolute; left: 56px; top: 644px; width: 330px;"><div style="margin-top: 0px"><div style="font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 16px; letter-spacing: 0.22em; color: #f0b04a; text-transform: uppercase; line-height: 22px; text-align: left;">Joe's kitchen</div><div style="font-family: 'Corben', serif; font-weight: 700; font-size: 40px; line-height: 46px; color: #f6ecd4; margin-top: 2px">To Begin</div><img src="assets/era/tonys/check-strip-39e180.webp" alt="" style="display: block; width: 330px; height: 10px; margin-top: 4px"></div><div style="margin-top: 8px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 27px; line-height: 1.12; color: #f6ecd4"><span>Garlic bread</span><span style="white-space: nowrap">.10</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 20px; line-height: 1.2; color: #b9bfd3; margin-top: 2px">Italian loaf, parsley butter, parmesan, baked crisp at the edges.</div></div><div style="margin-top: 8px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 27px; line-height: 1.12; color: #f6ecd4"><span>Antipasto for two</span><span style="white-space: nowrap">.40</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 20px; line-height: 1.2; color: #b9bfd3; margin-top: 2px">Salami, provolone, olives, artichoke hearts, roasted red peppers, torn bread.</div></div><div style="margin-top: 8px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 27px; line-height: 1.12; color: #f6ecd4"><span>Breadsticks</span><span style="white-space: nowrap">.05</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 20px; line-height: 1.2; color: #b9bfd3; margin-top: 2px">Long and salted, in a crock on every table.</div></div></div><div style="position: absolute; left: 408px; top: 650px; width: 1px; height: 336px; background: #f0b04a; opacity: 0.35"></div><div style="position: absolute; left: 430px; top: 644px; width: 330px;"><div style="margin-top: 0px"><div style="font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 16px; letter-spacing: 0.22em; color: #f0b04a; text-transform: uppercase; line-height: 22px; text-align: left;">Every night</div><div style="font-family: 'Corben', serif; font-weight: 700; font-size: 40px; line-height: 46px; color: #f6ecd4; margin-top: 2px">Specialty</div><img src="assets/era/tonys/check-strip-39e180.webp" alt="" style="display: block; width: 330px; height: 10px; margin-top: 4px"></div><div style="margin-top: 14px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 29px; line-height: 1.12; color: #ffd98a"><span>Spaghetti &amp; meatballs</span><span style="white-space: nowrap">.35</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 20px; line-height: 1.28; color: #b9bfd3; margin-top: 2px">Beef and pork meatballs, slow tomato and basil. Save the last meatball for your sweetheart.</div><div style="font-family: 'Crimson Pro', serif; font-style: italic; font-size: 19px; line-height: 1.25; color: #f0b04a; margin-top: 2px">For two, on one plate, .55</div></div></div><div style="position: absolute; left: 448px; top: 896px; width: 300px; height: 98px; background: #f5ead2; transform: rotate(-1.5deg); box-shadow: 0 6px 14px rgba(0,0,0,0.55)"><img src="assets/era/tonys/check-strip-39e180.webp" alt="" style="position: absolute; left: 0; top: 0; width: 300px; height: 12px"><div style="position: absolute; left: 16px; top: 16px; width: 268px"><div style="display: flex; justify-content: space-between; align-items: baseline"><div style="font-family: 'Corben', serif; font-weight: 700; font-size: 24px; line-height: 26px; color: #c3302a">Reserved</div><div style="font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 15px; letter-spacing: 0.16em; color: #1c2645">PARTY OF 2</div></div><div style="font-family: 'Crimson Pro', serif; font-size: 18px; line-height: 1.2; color: #1c2645; margin-top: 4px">Back door, by the barrels. Bella Notte.</div><div style="font-family: 'Allura', cursive; font-size: 30px; line-height: 30px; color: #22305a; margin-top: 2px">Butch and the lady</div></div></div><img src="assets/era/tonys/border-front-a19d86.webp" alt="" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px; opacity: 1"></div>`,
`<div style="position: relative; width: 816px; height: 1056px; overflow: hidden; background: #f5ead2"><img src="assets/era/tonys/wear-back-001436.webp" alt="" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px; opacity: 1"><img src="assets/era/_shared/paper-grain.webp" alt="" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px; opacity: 0.3"><div style="position: absolute; left: 56px; top: 58px; width: 704px;"><div style="display: flex; justify-content: space-between"><div style="font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.22em; color: #c3302a; text-transform: uppercase; line-height: 22px; text-align: left;">Before supper, a stroll</div><div style="font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.22em; color: #c3302a; text-transform: uppercase; line-height: 22px; text-align: left;">Est. 1901</div></div></div><div style="position: absolute; left: 56px; top: 80px; width: 704px;"><div style="font-family: 'Corben', serif; font-weight: 700; font-size: 58px; line-height: 64px; color: #1c2645">Up the Hill</div></div><div style="position: absolute; left: 51px; top: 149px; width: 714px; height: 260px; border: 2px solid #c3302a; box-sizing: border-box"></div><img src="assets/era/tonys/avenue-1905-042fce.webp" alt="Shaded walk and porches on a tree-lined avenue, about 1905" style="position: absolute; left: 56px; top: 154px; width: 704px; height: 250px"><div style="position: absolute; left: 56px; top: 414px; width: 520px;"><div style="font-family: 'Crimson Pro', serif; font-style: italic; font-size: 19px; line-height: 1.25; color: #4a4f66">The fine houses up the hill. Every one has a dog that knows our back door.</div></div><div style="position: absolute; left: 584px; top: 124px; width: 180px; height: 128px; background: #fbf5e6; transform: rotate(6deg); box-shadow: 0 4px 10px rgba(40,20,10,0.4)"><div style="position: absolute; left: 6px; top: 6px; width: 168px; height: 116px; border: 3px double #c3302a; box-sizing: border-box"></div><div style="position: absolute; left: 0; top: 14px; width: 180px; text-align: center; color: #1c2645"><div style="font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 14px; letter-spacing: 0.18em; line-height: 16px; color: #c3302a">DOG LICENSE</div><div style="font-family: 'Corben', serif; font-weight: 700; font-size: 38px; line-height: 42px">1910</div><div style="font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 16px; letter-spacing: 0.1em; line-height: 18px">No. 55</div><div style="font-family: 'Crimson Pro', serif; font-style: italic; font-size: 14px; line-height: 18px; margin-top: 2px">Wear on the collar at all times</div></div></div><div style="position: absolute; left: 56px; top: 444px; width: 340px;"><div style="margin-top: 0px"><div style="font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 16px; letter-spacing: 0.22em; color: #c3302a; text-transform: uppercase; line-height: 22px; text-align: left;">From Joe's stove</div><div style="font-family: 'Corben', serif; font-weight: 700; font-size: 40px; line-height: 46px; color: #1c2645; margin-top: 2px">Supper</div><img src="assets/era/tonys/check-strip-39e180.webp" alt="" style="display: block; width: 340px; height: 10px; margin-top: 4px"></div><div style="margin-top: 12px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 27px; line-height: 1.12; color: #1c2645"><span>Minestrone</span><span style="white-space: nowrap">.15</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 20px; line-height: 1.28; color: #3c4260; margin-top: 2px">Beans, greens, little pasta, tomato broth.</div></div><div style="margin-top: 12px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 27px; line-height: 1.12; color: #1c2645"><span>Chicken cacciatore</span><span style="white-space: nowrap">.45</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 20px; line-height: 1.28; color: #3c4260; margin-top: 2px">Braised with peppers, mushrooms, tomato.</div></div><div style="margin-top: 20px"><div style="font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 16px; letter-spacing: 0.22em; color: #c3302a; text-transform: uppercase; line-height: 22px; text-align: left;">Something sweet</div><div style="font-family: 'Corben', serif; font-weight: 700; font-size: 40px; line-height: 46px; color: #1c2645; margin-top: 2px">Dolci</div><img src="assets/era/tonys/check-strip-39e180.webp" alt="" style="display: block; width: 340px; height: 10px; margin-top: 4px"></div><div style="margin-top: 12px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 27px; line-height: 1.12; color: #1c2645"><span>Cannoli</span><span style="white-space: nowrap">.10</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 20px; line-height: 1.28; color: #3c4260; margin-top: 2px">Orange ricotta, chocolate chips, pistachio.</div></div><div style="margin-top: 12px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 27px; line-height: 1.12; color: #1c2645"><span>Spumoni</span><span style="white-space: nowrap">.10</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 20px; line-height: 1.28; color: #3c4260; margin-top: 2px">Cherry, pistachio and chocolate ice cream.</div></div></div><div style="position: absolute; left: 418px; top: 450px; width: 1px; height: 420px; background: #c3302a; opacity: 0.4"></div><div style="position: absolute; left: 440px; top: 444px; width: 320px;"><div style="margin-top: 0px"><div style="font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 16px; letter-spacing: 0.22em; color: #c3302a; text-transform: uppercase; line-height: 22px; text-align: left;">No wine, all fizz</div><div style="font-family: 'Corben', serif; font-weight: 700; font-size: 40px; line-height: 46px; color: #1c2645; margin-top: 2px">To Drink</div><img src="assets/era/tonys/check-strip-39e180.webp" alt="" style="display: block; width: 320px; height: 10px; margin-top: 4px"></div><div style="margin-top: 12px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 27px; line-height: 1.12; color: #1c2645"><span>Blood orange soda</span><span style="white-space: nowrap">.05</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 20px; line-height: 1.28; color: #3c4260; margin-top: 2px">Rosemary syrup, lemon, soda water.</div><div style="font-family: 'Crimson Pro', serif; font-style: italic; font-size: 19px; line-height: 1.25; color: #c3302a; margin-top: 2px">Red as the checked cloth.</div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 27px; line-height: 1.12; color: #1c2645"><span>Lemonade</span><span style="white-space: nowrap">.05</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 20px; line-height: 1.28; color: #3c4260; margin-top: 2px">Pressed lemons, cold from the ice box.</div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 27px; line-height: 1.12; color: #1c2645"><span>Espresso</span><span style="white-space: nowrap">.05</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 20px; line-height: 1.28; color: #3c4260; margin-top: 2px">Dark roast, a twist of peel.</div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Crimson Pro', serif; font-weight: 700; font-size: 27px; line-height: 1.12; color: #1c2645"><span>Cold milk</span><span style="white-space: nowrap">.03</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 20px; line-height: 1.28; color: #3c4260; margin-top: 2px">A tall glass, or a saucer.</div></div></div><div style="position: absolute; left: 440px; top: 828px; width: 320px;"><div style="border-top: 2px solid #c3302a; padding-top: 8px"><div style="font-family: 'Crimson Pro', serif; font-style: italic; font-size: 19px; line-height: 1.28; color: #1c2645">Every night my friend comes round the back for his supper. Tonight he brings a lady. Joe, the candle!</div><div style="font-family: 'Allura', cursive; font-size: 40px; line-height: 40px; color: #c3302a; margin-top: 2px; padding-left: 150px">Tony</div></div></div><div style="position: absolute; left: 56px; top: 982px; width: 704px;"><div style="display: flex; justify-content: space-between; font-family: 'Crimson Pro', serif; font-size: 16px; line-height: 1.3; color: #4a4f66"><span>Prices subject to change. Telephone Main 1909. Form T-55.</span><span>No muzzles out back. No cats, not even two.</span></div></div><img src="assets/era/tonys/border-back-1493b1.webp" alt="" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px; opacity: 1"></div>`
  ],fmtTonys.sheet);
}
