function fmtCorleone(f,spec,menu,poster){
  return fmtFaces([
`<div style="position: relative; width: 816px; height: 1056px; overflow: hidden; background: #1b120d"><img src="assets/era/corleone/light-front-657a93.webp" alt="" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px"><img src="assets/era/_shared/paper-grain.webp" alt="" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px; opacity: 0.25"><img src="assets/era/corleone/market-1940-9e7ac6.webp" alt="Pushcart market on Arthur Avenue, the Bronx, 1940" style="position: absolute; left: 0; top: 0; width: 816px; height: 400px"><div style="position: absolute; left: 40px; top: 286px; width: 520px;"><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.2em; color: #e39a3c; text-transform: uppercase; line-height: 22px;">Ristorante, the Bronx, N.Y.</div><div style="font-family: 'IM Fell English SC', serif; font-size: 72px; line-height: 72px; color: #f1e3c3; margin-top: 2px">Louis'</div></div><div style="position: absolute; left: 276px; top: 318px; width: 300px;"><div style="font-family: 'Spectral', serif; font-style: italic; font-size: 18px; line-height: 1.3; color: #cdb790">The pushcart market round our corner, where we buy every tomato.</div></div><div style="position: absolute; left: 592px; top: 236px; width: 190px; height: 190px; border-radius: 50%; background: #d0621f; transform: rotate(-6deg); box-shadow: 0 4px 14px rgba(0,0,0,0.55)"><div style="position: absolute; left: 9px; top: 9px; width: 172px; height: 172px; border-radius: 50%; border: 2px solid #f7f2e4; box-sizing: border-box"></div><div style="position: absolute; left: 0; top: 34px; width: 190px; text-align: center; color: #f7f2e4"><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 16px; letter-spacing: 0.2em; line-height: 22px">THE BEST</div><div style="font-family: 'IM Fell English SC', serif; font-size: 64px; line-height: 62px">Veal</div><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 16px; letter-spacing: 0.14em; line-height: 20px">IN THE CITY</div></div></div><div style="position: absolute; left: 40px; top: 424px; width: 366px;"><div style="margin-top: 0px"><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.2em; color: #e39a3c; text-transform: uppercase; line-height: 22px;">To start</div><div style="font-family: 'IM Fell English SC', serif; font-size: 42px; line-height: 44px; color: #f1e3c3; margin-top: 2px">Antipasti</div><div style="height: 3px; background: #e39a3c; margin-top: 4px; opacity: 0.9"></div><div style="height: 1px; background: #e39a3c; margin-top: 2px; opacity: 0.7"></div></div><div style="margin-top: 14px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Spectral', serif; font-weight: 700; font-size: 27px; line-height: 1.15; color: #f1e3c3"><span>Antipasto, wedding style</span><span>.65</span></div><div style="font-family: 'Spectral', serif; font-size: 20px; line-height: 1.3; color: #cdb790; margin-top: 3px">Salami, aged provolone, olives and roasted peppers, at room temperature.</div></div><div style="margin-top: 14px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Spectral', serif; font-weight: 700; font-size: 27px; line-height: 1.15; color: #f1e3c3"><span>Arancini</span><span>.40</span></div><div style="font-family: 'Spectral', serif; font-size: 20px; line-height: 1.3; color: #cdb790; margin-top: 3px">Crisp risotto balls, fried golden round a melting mozzarella heart.</div></div><div style="margin-top: 26px"><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.2em; color: #e39a3c; text-transform: uppercase; line-height: 22px;">By hand, every morning</div><div style="font-family: 'IM Fell English SC', serif; font-size: 42px; line-height: 44px; color: #f1e3c3; margin-top: 2px">Pasta</div><div style="height: 3px; background: #e39a3c; margin-top: 4px; opacity: 0.9"></div><div style="height: 1px; background: #e39a3c; margin-top: 2px; opacity: 0.7"></div></div><div style="margin-top: 14px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Spectral', serif; font-weight: 700; font-size: 27px; line-height: 1.15; color: #f1e3c3"><span>Rigatoni, Sunday gravy</span><span>.85</span></div><div style="font-family: 'Spectral', serif; font-size: 20px; line-height: 1.3; color: #cdb790; margin-top: 3px">Pork and beef meatballs, fennel sausage, slow tomato, pecorino.</div></div><div style="font-family: 'Spectral', serif; font-size: 16px; line-height: 1.3; color: #cdb790; margin-top: 22px">We cook with Genco Pura olive oil. Prices subject to change. OLinville 2-1972. Form L-46.</div></div><div style="position: absolute; left: 427px; top: 428px; width: 1px; height: 540px; background: #e39a3c; opacity: 0.35"></div><div style="position: absolute; left: 448px; top: 424px; width: 328px;"><div style="margin-top: 0px"><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.2em; color: #e39a3c; text-transform: uppercase; line-height: 22px;">Specialità della casa</div><div style="font-family: 'IM Fell English SC', serif; font-size: 42px; line-height: 44px; color: #f1e3c3; margin-top: 2px">The Veal</div><div style="height: 3px; background: #e39a3c; margin-top: 4px; opacity: 0.9"></div><div style="height: 1px; background: #e39a3c; margin-top: 2px; opacity: 0.7"></div></div><div style="margin-top: 14px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Spectral', serif; font-weight: 700; font-size: 28px; line-height: 1.15; color: #f1e3c3"><span>Veal scaloppine</span><span>1.72</span></div><div style="font-family: 'Spectral', serif; font-size: 20px; line-height: 1.3; color: #cdb790; margin-top: 3px">Thin cutlets pan-fried in butter, with Marsala wine and mushrooms.</div><div style="font-family: 'Spectral', serif; font-style: italic; font-size: 18px; line-height: 1.25; color: #e39a3c; margin-top: 3px">Pounded to order. Allow a few minutes.</div></div></div><div style="position: absolute; left: 448px; top: 656px; width: 328px;"><div style="border: 2px solid #e39a3c; padding: 12px 16px 14px; box-sizing: border-box; background: rgba(0,0,0,0.28)"><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 16px; letter-spacing: 0.2em; color: #e39a3c; text-transform: uppercase; line-height: 22px;">Complete dinner</div><div style="display: flex; justify-content: space-between; align-items: baseline; margin-top: 4px"><div style="font-family: 'IM Fell English SC', serif; font-size: 30px; line-height: 32px; color: #f1e3c3">The family dinner</div><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 28px; color: #f1e3c3">2.50</div></div><div style="font-family: 'Spectral', serif; font-size: 20px; line-height: 1.3; color: #cdb790; margin-top: 6px">Antipasto, rigatoni and gravy, the veal, cannoli, espresso.</div></div></div><div style="position: absolute; left: 470px; top: 836px; width: 300px; height: 140px; background: #f7f2e4; transform: rotate(3.5deg); box-shadow: 0 6px 14px rgba(0,0,0,0.6); border: 1px solid #cfc3a6"><div style="position: absolute; left: 22px; top: 0; width: 16px; height: 140px; background: #ead2c9"></div><div style="position: absolute; left: 22px; top: 0; width: 2px; height: 140px; background: #d9b9ad"></div><div style="position: absolute; left: 36px; top: 0; width: 2px; height: 140px; background: #d9b9ad"></div><div style="position: absolute; left: 54px; top: 12px; width: 234px; text-align: center"><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 16px; letter-spacing: 0.2em; color: #d0621f; text-transform: uppercase; line-height: 22px;">Bomboniera</div><div style="font-family: 'IM Fell English SC', serif; font-size: 28px; line-height: 30px; color: #2b1b13">Connie &amp; Carlo</div><div style="font-family: 'Spectral', serif; font-style: italic; font-size: 16px; line-height: 20px; color: #57463a">Long Beach, 1945</div></div><img src="assets/era/corleone/almonds-485e1e.webp" alt="" style="position: absolute; left: 62px; top: 74px; width: 218px; height: 61px"></div></div>`,
`<div style="position: relative; width: 816px; height: 1056px; overflow: hidden; background: #1b120d"><img src="assets/era/corleone/light-back-5df69f.webp" alt="" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px"><img src="assets/era/_shared/paper-grain.webp" alt="" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px; opacity: 0.25"><div style="position: absolute; left: 40px; top: 40px; width: 736px; height: 368px; background: #c9a24a"></div><img src="assets/era/corleone/garden-efaa80.webp" alt="Oranges and red wine at a garden table" style="position: absolute; left: 43px; top: 43px; width: 730px; height: 362px"><div style="position: absolute; left: 626px; top: 414px; width: 140px; height: 103px; padding: 4px; background: #c9a24a; transform: rotate(2deg); box-shadow: 0 6px 14px rgba(0,0,0,0.5)"><img src="assets/era/corleone/orange-plate-3ffbc5.webp" alt="Botanical print of the bitter orange: leaves, blossom, a cut fruit and a whole orange" style="display: block; width: 140px; height: 103px"></div><div style="position: absolute; left: 40px; top: 422px; width: 440px;"><div style="font-family: 'IM Fell English SC', serif; font-size: 34px; line-height: 36px; color: #f1e3c3">An orange on every table</div><div style="font-family: 'Spectral', serif; font-style: italic; font-size: 18px; line-height: 1.3; color: #cdb790; margin-top: 4px">Sunday in the garden: fruit, red wine, family.</div></div><div style="position: absolute; left: 40px; top: 524px; width: 366px;"><div style="margin-top: 0px"><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.2em; color: #e39a3c; text-transform: uppercase; line-height: 22px;">From Nazorine's</div><div style="font-family: 'IM Fell English SC', serif; font-size: 38px; line-height: 44px; color: #f1e3c3; margin-top: 2px">Cannoli to go</div><div style="height: 3px; background: #e39a3c; margin-top: 4px; opacity: 0.9"></div><div style="height: 1px; background: #e39a3c; margin-top: 2px; opacity: 0.7"></div></div><div style="margin-top: 14px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Spectral', serif; font-weight: 700; font-size: 27px; line-height: 1.15; color: #f1e3c3"><span>Cannoli</span><span>.25</span></div><div style="font-family: 'Spectral', serif; font-size: 20px; line-height: 1.3; color: #cdb790; margin-top: 3px">Crisp shells, orange-scented ricotta, dark chocolate, crushed pistachio.</div></div></div><img src="assets/era/corleone/cannoli-box-1fae94.webp" alt="" style="position: absolute; left: 30px; top: 710px; width: 250px; height: 159px"><div style="position: absolute; left: 44px; top: 729px; width: 150px; height: 86px; border-radius: 50%; border: 2px solid #d0621f; box-sizing: border-box; text-align: center; padding-top: 14px"><div style="font-family: 'IM Fell English SC', serif; font-size: 24px; line-height: 24px; color: #2b1b13">Nazorine</div><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 14px; letter-spacing: 0.14em; line-height: 20px; color: #d0621f">PASTRY</div></div><div style="position: absolute; left: 296px; top: 722px; width: 132px;"><div style="font-family: 'Spectral', serif; font-style: italic; font-size: 18px; line-height: 1.3; color: #cdb790">Leave the gun. Take the cannoli.</div></div><div style="position: absolute; left: 40px; top: 884px; width: 388px;"><div style="font-family: 'Spectral', serif; font-style: italic; font-size: 18px; line-height: 1.3; color: #f1e3c3">“A little bit of sugar, and that’s my trick.”</div></div><div style="position: absolute; left: 250px; top: 942px; width: 200px;"><div style="font-family: 'Mrs Saint Delafield', cursive; font-size: 36px; line-height: 34px; color: #e39a3c">Pete Clemenza</div></div><div style="position: absolute; left: 448px; top: 524px; width: 328px;"><div style="margin-top: 0px"><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.2em; color: #e39a3c; text-transform: uppercase; line-height: 22px;">After dinner</div><div style="font-family: 'IM Fell English SC', serif; font-size: 42px; line-height: 44px; color: #f1e3c3; margin-top: 2px">Caffè &amp; Bar</div><div style="height: 3px; background: #e39a3c; margin-top: 4px; opacity: 0.9"></div><div style="height: 1px; background: #e39a3c; margin-top: 2px; opacity: 0.7"></div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Spectral', serif; font-weight: 700; font-size: 27px; line-height: 1.15; color: #f1e3c3"><span>Espresso</span><span>.10</span></div><div style="font-family: 'Spectral', serif; font-size: 20px; line-height: 1.3; color: #cdb790; margin-top: 3px">Dark roast, a curl of lemon peel.</div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Spectral', serif; font-weight: 700; font-size: 27px; line-height: 1.15; color: #f1e3c3"><span>Blood orange soda</span><span>.15</span></div><div style="font-family: 'Spectral', serif; font-size: 20px; line-height: 1.3; color: #cdb790; margin-top: 3px">Ruby citrus syrup, cold seltzer.</div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Spectral', serif; font-weight: 700; font-size: 27px; line-height: 1.15; color: #f1e3c3"><span>Chianti</span><span>.35</span></div><div style="font-family: 'Spectral', serif; font-size: 20px; line-height: 1.3; color: #cdb790; margin-top: 3px">By the glass, from the straw bottle.</div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Spectral', serif; font-weight: 700; font-size: 27px; line-height: 1.15; color: #f1e3c3"><span>Anisette</span><span>.30</span></div><div style="font-family: 'Spectral', serif; font-size: 20px; line-height: 1.3; color: #cdb790; margin-top: 3px">Sweet cordial. Make him an offer.</div></div></div><div style="position: absolute; left: 448px; top: 890px; width: 328px;"><div style="border-top: 2px solid #e39a3c; padding-top: 6px"><div style="font-family: 'Spectral', serif; font-weight: 700; font-size: 16px; letter-spacing: 0.2em; color: #e39a3c; text-transform: uppercase; line-height: 22px;">House customs</div><div style="font-family: 'Spectral', serif; font-size: 17px; line-height: 1.3; color: #f1e3c3; margin-top: 3px">Old-fashioned plumbing out back.</div><div style="font-family: 'Spectral', serif; font-size: 17px; line-height: 1.3; color: #f1e3c3; margin-top: 3px">Police officers dine here often.</div><div style="font-family: 'Spectral', serif; font-size: 17px; line-height: 1.3; color: #f1e3c3; margin-top: 3px">Luca sleeps with the fishes.</div></div></div></div>`
  ],fmtCorleone.sheet);
}
