function fmtDelancey(f,spec,menu,poster){
  return fmtFaces([
`<div style="position: relative; width: 960px; height: 1344px; overflow: hidden; background: #eadcbc"><img src="assets/era/_shared/paper-grain.webp" alt="" aria-hidden="true" style="position: absolute; left: 0; top: 0; width: 960px; height: 1344px; display: block; opacity: 0.55"><img src="assets/era/delancey/wear-paper-e8c238.webp" alt="" aria-hidden="true" style="position: absolute; left: 0; top: 0; width: 960px; height: 1344px; display: block"><div style="position: absolute; left: 48px; top: 40px; width: 864px; display: flex; justify-content: space-between"><div style="font-family: 'Crimson Pro', serif; font-weight: 600; font-size: 18px; letter-spacing: 0.24em; color: #9b3b1f; text-transform: uppercase; line-height: 1.1;">Lunch room &amp; delicatessen</div><div style="font-family: 'Crimson Pro', serif; font-weight: 600; font-size: 18px; letter-spacing: 0.24em; color: #9b3b1f; text-transform: uppercase; line-height: 1.1;">Lower East Side</div><div style="font-family: 'Crimson Pro', serif; font-weight: 600; font-size: 18px; letter-spacing: 0.24em; color: #9b3b1f; text-transform: uppercase; line-height: 1.1;">Bill of fare, 1933</div></div><div style="position: absolute; left: 48px; top: 66px; border: 2px solid #9b3b1f; padding: 4px; background: #eadcbc"><img src="assets/era/delancey/street-rivington-daf94f.webp" alt="A Lower East Side market street on a Sunday morning, pushcarts of fruit, shoppers and blurred passers-by in long coats, in warm sepia haze" style="display: block; width: 852px; height: 500px"></div><div style="position: absolute; left: 78px; top: 92px; width: 804px; height: 112px; background: #2a1c12; box-sizing: border-box; box-shadow: 0 6px 16px rgba(20,12,6,0.55)"><div style="position: absolute; left: 7px; top: 7px; right: 7px; bottom: 7px; border: 2px solid #9b3b1f"></div><div style="position: absolute; left: 13px; top: 13px; right: 13px; bottom: 13px; border: 1px solid #6d5a45"></div><div style="position: absolute; left: 0; right: 0; top: 6px; text-align: center; font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 90px; line-height: 100px; letter-spacing: 0.05em; color: #eadcbc; white-space: nowrap">FAT MOE&rsquo;S</div><div style="position: absolute; left: 20px; top: 32px; width: 104px; text-align: center; font-family: 'Crimson Pro', serif; font-weight: 600; font-size: 16px; letter-spacing: 0.2em; color: #eadcbc; line-height: 1.5">HOT<br>LUNCH</div><div style="position: absolute; left: 680px; top: 32px; width: 104px; text-align: center; font-family: 'Crimson Pro', serif; font-weight: 600; font-size: 16px; letter-spacing: 0.2em; color: #eadcbc; line-height: 1.5">OPEN<br>LATE</div></div><div style="position: absolute; left: 54px; top: 530px; height: 42px; background: #eadcbc; padding: 0 16px 0 12px; box-sizing: border-box; font-family: 'Crimson Pro', serif; font-style: italic; font-size: 18px; line-height: 42px; color: #2a1c12; white-space: nowrap">The old neighbourhood, Sunday morning. We grew up on this corner.</div><div style="position: absolute; left: 72px; top: 356px; width: 214px; height: 140px; background: #efe3bf; box-sizing: border-box; box-shadow: 0 4px 10px rgba(30,20,10,0.45); transform: rotate(5deg)"><div style="position: absolute; left: 0; top: 0; width: 46px; height: 140px; background: #9b3b1f"></div><div style="position: absolute; left: 46px; top: 0; width: 0; height: 140px; border-left: 2px dotted #efe3bf"></div><div style="position: absolute; left: 0; top: 22px; width: 46px; text-align: center; font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 22px; line-height: 1.05; color: #efe3bf">No.<br>22</div><div style="position: absolute; left: 13px; top: 86px; width: 20px; height: 20px; border-radius: 50%; border: 2px solid #efe3bf; box-sizing: border-box"></div><div style="position: absolute; left: 58px; top: 10px; right: 10px"><div style="font-family: 'Crimson Pro', serif; font-weight: 600; font-size: 14px; letter-spacing: 0.18em; color: #9b3b1f; line-height: 1">WATCH CLAIM CHECK</div><div style="font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 18px; color: #2a1c12; line-height: 1.15; margin-top: 6px">One gent&rsquo;s gold pocket watch</div><div style="font-family: 'Crimson Pro', serif; font-size: 15px; color: #2a1c12; line-height: 1.25; margin-top: 4px">Wound, set and oiled.<br>Not yet called for.</div></div></div><div style="position: absolute; left: 646px; top: 370px; width: 252px; background: #f4ecd8; padding: 8px 8px 0; box-sizing: border-box; box-shadow: 0 4px 10px rgba(30,20,10,0.5); transform: rotate(-2deg)"><div style="border: 1px solid #9b3b1f"><img src="assets/era/delancey/locker-541-21e6a1.webp" alt="A hand turning a key in a station locker numbered 541" style="display: block; width: 234px; height: 150px"></div><div style="font-family: 'Crimson Pro', serif; font-style: italic; font-size: 16px; line-height: 34px; color: #2a1c12; text-align: center; white-space: nowrap">Station locker. The key? Ask the clock.</div></div><div style="position: absolute; left: 48px; top: 600px; width: 478px"><div style="margin-top: 0px"><div style="font-family: 'Crimson Pro', serif; font-weight: 600; font-size: 18px; letter-spacing: 0.24em; color: #9b3b1f; text-transform: uppercase; line-height: 1.1;">Made fresh every morning</div><div style="font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 40px; line-height: 44px; color: #2a1c12; margin-top: 4px; white-space: nowrap">AT THE COUNTER</div><div style="height: 4px; background: #9b3b1f; margin-top: 4px"></div><div style="height: 1px; background: #9b3b1f; margin-top: 3px"></div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 27px; line-height: 1.18; color: #2a1c12"><span>Delancey knishes</span><span style="color: #9b3b1f">.10</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 21px; line-height: 1.28; color: #5a4636; margin-top: 2px">Potato and sweet onion in puff pastry, hot mustard.</div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 27px; line-height: 1.18; color: #2a1c12"><span>Bagel crisps &amp; schmear</span><span style="color: #9b3b1f">.20</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 21px; line-height: 1.28; color: #5a4636; margin-top: 2px">Bagel rounds, chive cream cheese, smoked salmon.</div></div><div style="margin-top: 14px"><div style="font-family: 'Crimson Pro', serif; font-weight: 600; font-size: 18px; letter-spacing: 0.24em; color: #9b3b1f; text-transform: uppercase; line-height: 1.1;">Hot plates, noon to closing</div><div style="font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 40px; line-height: 44px; color: #2a1c12; margin-top: 4px; white-space: nowrap">FROM THE KITCHEN</div><div style="height: 4px; background: #9b3b1f; margin-top: 4px"></div><div style="height: 1px; background: #9b3b1f; margin-top: 3px"></div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 27px; line-height: 1.18; color: #2a1c12"><span>Moe&rsquo;s brisket</span><span style="color: #9b3b1f">.45</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 21px; line-height: 1.28; color: #5a4636; margin-top: 2px">Slow braised on onions, paprika and tomato gravy.</div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 27px; line-height: 1.18; color: #2a1c12"><span>Noodles&rsquo; kugel</span><span style="color: #9b3b1f">.15</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 21px; line-height: 1.28; color: #5a4636; margin-top: 2px">Baked egg noodles, farmer cheese, raisins, cinnamon.</div></div></div><div style="position: absolute; left: 554px; top: 594px; width: 358px; height: 450px; background: #2a1c12; box-sizing: border-box; border-radius: 6px 6px 0 0; padding: 18px 20px 0"><div style="position: absolute; left: 6px; top: 6px; right: 6px; bottom: 6px; border: 1px solid #6d5a45; border-radius: 4px 4px 0 0"></div><div style="position: relative"><div style="margin-top: 0px"><div style="font-family: 'Crimson Pro', serif; font-weight: 600; font-size: 18px; letter-spacing: 0.24em; color: #e3a865; text-transform: uppercase; line-height: 1.1;">Friends of the house</div><div style="font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 40px; line-height: 44px; color: #eadcbc; margin-top: 4px; white-space: nowrap">BACK ROOM</div><div style="height: 4px; background: #9b3b1f; margin-top: 4px"></div><div style="height: 1px; background: #9b3b1f; margin-top: 3px"></div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 27px; line-height: 1.18; color: #eadcbc"><span>Rye sour</span><span style="color: #e3a865">.35</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 21px; line-height: 1.28; color: #d8c9a8; margin-top: 2px">Rye, lemon, sugar, egg white, a dash of bitters.</div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 27px; line-height: 1.18; color: #eadcbc"><span>Cold tea</span><span style="color: #e3a865">.25</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 21px; line-height: 1.28; color: #d8c9a8; margin-top: 2px">Strong, brown, from the pot. Ask for it by name.</div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 12px; font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 27px; line-height: 1.18; color: #eadcbc"><span>Egg cream</span><span style="color: #e3a865">.05</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 21px; line-height: 1.28; color: #d8c9a8; margin-top: 2px">Chocolate, milk, seltzer. No egg.</div></div><div style="font-family: 'Crimson Pro', serif; font-style: italic; font-size: 18px; line-height: 1.3; color: #d8c9a8; margin-top: 14px">Everything in china teacups. Repeal is coming; we&rsquo;ll give it a funeral.</div></div></div><div style="position: absolute; left: 48px; top: 1068px; width: 864px; height: 152px; background: #2a1c12; box-sizing: border-box"><div style="position: absolute; left: 6px; top: 6px; right: 6px; bottom: 6px; border: 1px solid #6d5a45"></div><div style="position: absolute; left: 0; right: 0; top: 0; height: 4px; background: #9b3b1f"></div></div><div style="position: absolute; left: 66px; top: 1080px; width: 214px; height: 128px; background: #f4f1e6; box-sizing: border-box; border: 1px solid #c9c1a8; box-shadow: 0 4px 10px rgba(30,20,10,0.4); transform: rotate(-4deg)"><div style="position: absolute; left: 8px; top: 8px; right: 8px; bottom: 8px; border: 1px solid #d8d0b8"></div><div style="position: absolute; left: 0; top: 62px; width: 214px; height: 4px; background: #9b3b1f"></div><div style="position: absolute; left: 0; top: 65px; width: 214px; height: 1px; background: #f4f1e6"></div><div style="position: absolute; left: 105px; top: 0; width: 4px; height: 128px; background: #9b3b1f"></div><div style="position: absolute; left: 53px; top: 24px; width: 108px; height: 80px; border-radius: 50%; background: #eadcbc; border: 2px solid #9b3b1f; box-sizing: border-box; text-align: center; padding-top: 12px"><div style="font-family: 'Crimson Pro', serif; font-weight: 600; font-size: 14px; letter-spacing: 0.12em; color: #9b3b1f; line-height: 1">ONE ONLY</div><div style="font-family: 'Old Standard TT', serif; font-weight: 700; font-size: 15px; color: #2a1c12; line-height: 1.12; margin-top: 4px">Charlotte<br>russe</div></div><div style="position: absolute; left: 12px; bottom: 6px; font-family: 'Crimson Pro', serif; font-style: italic; font-size: 14px; color: #5a4636; line-height: 1">Deliver upstairs</div></div><div style="position: absolute; left: 310px; top: 1082px; width: 578px"><div style="font-family: 'Crimson Pro', serif; font-weight: 600; font-size: 18px; letter-spacing: 0.24em; color: #e3a865; text-transform: uppercase; line-height: 1.1;">From the bakery case, one only</div><div style="display: flex; justify-content: space-between; align-items: baseline; margin-top: 2px; font-family: 'Old Standard TT', serif; font-weight: 700; color: #eadcbc"><span style="font-size: 54px; line-height: 60px">Charlotte russe</span><span style="font-size: 54px; line-height: 60px; color: #e3a865">5&cent;</span></div><div style="font-family: 'Crimson Pro', serif; font-size: 21px; line-height: 1.28; color: #d8c9a8">Sponge in a paper cup, vanilla cream piped tall, a cherry.<br><i style="color: #eadcbc">Try not to eat it on the stairs.</i></div></div><div style="position: absolute; left: 48px; top: 1238px; width: 864px; display: flex; justify-content: space-between; align-items: flex-end"><div style="font-family: 'Crimson Pro', serif; font-size: 16px; line-height: 1.32; color: #5a4636">Prices subject to change. Storeroom closed afternoons for Amapola dance practice.<br>Music most nights, Cockeye wants to sit in with the band.<br>Bill of fare No. 1933. Telephone ORchard 4-1968. Same table as always.</div><div style="text-align: right; flex: none; margin-left: 16px"><div style="font-family: 'Crimson Pro', serif; font-style: italic; font-size: 16px; color: #5a4636; line-height: 1.2">Your table is waiting, boys.</div><div style="font-family: 'Mrs Saint Delafield', cursive; font-size: 46px; color: #9b3b1f; line-height: 0.9; margin-top: 2px">Moe</div></div></div></div>`
  ],fmtDelancey.sheet);
}
