function fmtBookshopCafe(f,spec,menu,poster){
  return fmtFaces([
`<div style="position: relative; width: 816px; height: 1056px; overflow: hidden; background: #f8f4ec"><img src="assets/era/_shared/paper-grain.webp" alt="" aria-hidden="true" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px; display: block; opacity: 0.22"><div style="position: absolute; left: 0; top: 0; width: 816px; height: 14px; background: #7e1f2d"></div><div style="position: absolute; left: 0; top: 17px; width: 816px; height: 3px; background: #b08a45"></div><div style="position: absolute; left: 56px; top: 44px; width: 704px; display: flex; justify-content: space-between"><div style="font-family: 'Lora', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.22em; color: #7e1f2d; text-transform: uppercase; line-height: 1;">Upper West Side, New York</div><div style="font-family: 'Lora', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.22em; color: #2b1f1b; text-transform: uppercase; line-height: 1;">Open 7 a.m. to 11 p.m.</div></div><div style="position: absolute; left: 56px; top: 74px; width: 704px; display: flex; justify-content: center"><div style="display: flex; align-items: center; gap: 17px; font-family: 'Libre Caslon Display', serif; font-size: 88px; line-height: 1; color: #2b1f1b; letter-spacing: 0.03em"><span>FOX</span><span style="font-family: 'Lora', serif; font-weight: 700; font-size: 24px; letter-spacing: 0.12em; background: #2b1f1b; color: #f8f4ec; padding: 8px 13px; line-height: 1">&amp; SONS</span><span>BOOKS</span></div></div><div style="position: absolute; left: 56px; top: 176px; width: 704px; display: flex; align-items: center; gap: 18px"><div style="flex: 1; height: 2px; background: #b08a45"></div><div style="font-family: 'Libre Caslon Display', serif; font-size: 40px; line-height: 1; color: #7e1f2d">The Cafe</div><div style="flex: 1; height: 2px; background: #b08a45"></div></div><div style="position: absolute; left: 56px; top: 238px; width: 704px; height: 332px; outline: 2px solid #7e1f2d; outline-offset: 5px; background: #ddd"><img src="assets/era/bookshopcafe/still-facade-9b6b73.webp" alt="The Fox and Sons Books store on Broadway, gold sign letters over burgundy awnings" style="display: block; width: 704px; height: 332px"></div><div style="position: absolute; left: 56px; top: 584px; width: 704px; display: flex; justify-content: space-between; font-family: 'Lora', serif; font-style: italic; font-size: 16px; color: #6a5a50"><span>Our new store on Broadway. Bring any book to your table.</span><span>Story hour Saturdays at 11</span></div><div style="position: absolute; left: 56px; top: 624px; width: 704px"><div style="font-family: 'Lora', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.22em; color: #7e1f2d; text-transform: uppercase; line-height: 1; margin-bottom: 10px">House roast, any size, any strength</div><div style="border-bottom: 3px solid #b08a45; padding-bottom: 4px;"><div style="display: inline-block; background: #7e1f2d; color: #f8f4ec; font-family: 'Libre Caslon Display', serif; font-size: 42px; line-height: 1; padding: 8px 18px 10px; letter-spacing: 0.005em">The coffee bar</div></div><div style="margin-top: 10px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 16px; font-family: 'Libre Caslon Display', serif; font-size: 28px; line-height: 1.15; color: #2b1f1b"><span>Fox Books cafe cappuccino</span><span style="color: #7e1f2d">2.95</span></div><div style="font-family: 'Lora', serif; font-size: 20px; line-height: 1.38; color: #2b1f1b; margin-top: 3px">Two shots of decaf espresso, steamed milk and a deep crown of foam.</div></div><div style="margin-top: 8px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 16px; font-family: 'Libre Caslon Display', serif; font-size: 28px; line-height: 1.15; color: #2b1f1b"><span>Caff&egrave; latte</span><span style="color: #7e1f2d">2.75</span></div><div style="font-family: 'Lora', serif; font-size: 20px; line-height: 1.38; color: #2b1f1b; margin-top: 3px">Espresso with plenty of steamed milk under a thin layer of foam.</div></div><div style="margin-top: 8px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 16px; font-family: 'Libre Caslon Display', serif; font-size: 28px; line-height: 1.15; color: #2b1f1b"><span>Coffee of the day</span><span style="color: #7e1f2d">1.52</span></div><div style="font-family: 'Lora', serif; font-size: 20px; line-height: 1.38; color: #2b1f1b; margin-top: 3px">Our house roast, brewed fresh every hour. Refills are free.</div></div><div style="margin-top: 8px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 16px; font-family: 'Libre Caslon Display', serif; font-size: 28px; line-height: 1.15; color: #2b1f1b"><span>Hot cocoa</span><span style="color: #7e1f2d">1.95</span></div><div style="font-family: 'Lora', serif; font-size: 20px; line-height: 1.38; color: #2b1f1b; margin-top: 3px">Dark chocolate melted into hot milk, with whipped cream.</div></div></div><div style="position: absolute; left: 632px; top: 214px; width: 132px; height: 132px; border: 4px solid #7e1f2d; border-radius: 50%; box-sizing: border-box; transform: rotate(-12deg); opacity: 0.9; background: rgba(248,244,236,0.92)"><div style="position: absolute; left: 6px; top: 6px; width: 112px; height: 112px; border: 1.5px solid #7e1f2d; border-radius: 50%; box-sizing: border-box"></div><div style="position: absolute; left: 0; top: 24px; width: 124px; text-align: center; font-family: 'Lora', serif; font-weight: 700; font-size: 14px; letter-spacing: 0.16em; color: #7e1f2d">FOX BOOKS</div><div style="position: absolute; left: 0; top: 42px; width: 124px; text-align: center; font-family: 'Libre Caslon Display', serif; font-size: 25px; line-height: 1; color: #7e1f2d">Now<br>Open</div><div style="position: absolute; left: 0; top: 96px; width: 124px; text-align: center; font-family: 'Lora', serif; font-weight: 700; font-size: 14px; letter-spacing: 0.16em; color: #7e1f2d">FALL 1998</div></div><img src="assets/era/bookshopcafe/wear-front-e2d4c8.webp" alt="" aria-hidden="true" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px; display: block"></div>`,
`<div style="position: relative; width: 816px; height: 1056px; overflow: hidden; background: #f8f4ec"><img src="assets/era/_shared/paper-grain.webp" alt="" aria-hidden="true" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px; display: block; opacity: 0.22"><div style="position: absolute; left: 0; top: 0; width: 816px; height: 14px; background: #7e1f2d"></div><div style="position: absolute; left: 0; top: 17px; width: 816px; height: 3px; background: #b08a45"></div><div style="position: absolute; left: 56px; top: 46px"><div style="font-family: 'Lora', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.22em; color: #7e1f2d; text-transform: uppercase; line-height: 1;">Order at the counter, we bring it to you</div></div><div style="position: absolute; left: 56px; top: 78px; font-family: 'Libre Caslon Display', serif; font-size: 66px; line-height: 1; color: #2b1f1b">The Menu</div><div style="position: absolute; left: 386px; top: 92px; width: 374px; display: flex; justify-content: flex-end"><div style="display: flex; align-items: center; gap: 8px; font-family: 'Libre Caslon Display', serif; font-size: 40px; line-height: 1; color: #2b1f1b; letter-spacing: 0.03em"><span>FOX</span><span style="font-family: 'Lora', serif; font-weight: 700; font-size: 14px; letter-spacing: 0.12em; background: #2b1f1b; color: #f8f4ec; padding: 4px 7px; line-height: 1">&amp; SONS</span><span>BOOKS</span></div></div><div style="position: absolute; left: 56px; top: 166px; width: 704px; height: 2px; background: #b08a45"></div><div style="position: absolute; left: 56px; top: 188px; width: 340px"><div style="border-bottom: 3px solid #b08a45; padding-bottom: 4px;"><div style="display: inline-block; background: #7e1f2d; color: #f8f4ec; font-family: 'Libre Caslon Display', serif; font-size: 36px; line-height: 1; padding: 8px 18px 10px; letter-spacing: 0.005em">The kitchen</div></div><div style="margin-top: 18px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 16px; font-family: 'Libre Caslon Display', serif; font-size: 26px; line-height: 1.15; color: #2b1f1b"><span>Toasted mini bagels</span><span style="color: #7e1f2d">3.25</span></div><div style="font-family: 'Lora', serif; font-size: 20px; line-height: 1.38; color: #2b1f1b; margin-top: 3px">Three to an order, with spring onion cream cheese and cracked pepper.</div></div><div style="margin-top: 18px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 16px; font-family: 'Libre Caslon Display', serif; font-size: 26px; line-height: 1.15; color: #2b1f1b"><span>Turkey and brie melt</span><span style="color: #7e1f2d">6.50</span></div><div style="font-family: 'Lora', serif; font-size: 20px; line-height: 1.38; color: #2b1f1b; margin-top: 3px">Cranberry sauce on buttered sourdough, pressed hot until the cheese runs.</div></div><div style="height: 22px"></div><div style="border-bottom: 3px solid #b08a45; padding-bottom: 4px;"><div style="display: inline-block; background: #7e1f2d; color: #f8f4ec; font-family: 'Libre Caslon Display', serif; font-size: 36px; line-height: 1; padding: 8px 18px 10px; letter-spacing: 0.005em">Bakery case</div></div><div style="margin-top: 18px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 16px; font-family: 'Libre Caslon Display', serif; font-size: 26px; line-height: 1.15; color: #2b1f1b"><span>New York cheesecake</span><span style="color: #7e1f2d">3.95</span></div><div style="font-family: 'Lora', serif; font-size: 20px; line-height: 1.38; color: #2b1f1b; margin-top: 3px">Baked rich and dense, with sugared fresh strawberries.</div></div><div style="margin-top: 18px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 16px; font-family: 'Libre Caslon Display', serif; font-size: 26px; line-height: 1.15; color: #2b1f1b"><span>Chocolate chip cookie</span><span style="color: #7e1f2d">1.25</span></div><div style="font-family: 'Lora', serif; font-size: 20px; line-height: 1.38; color: #2b1f1b; margin-top: 3px">Big and chewy, out of the oven every morning.</div></div><div style="margin-top: 22px; width: 340px; box-sizing: border-box; border: 2px dashed #7e1f2d; background: #fffdf8; padding: 12px 16px 12px"><div style="display: flex; justify-content: space-between; align-items: baseline"><span style="font-family: 'Libre Caslon Display', serif; font-size: 30px; line-height: 1; color: #7e1f2d">Free hot cocoa</span><span style="font-family: 'Lora', serif; font-weight: 700; font-size: 14px; letter-spacing: 0.18em; color: #6a5a50">CLIP</span></div><div style="font-family: 'Lora', serif; font-size: 17px; line-height: 1.35; color: #2b1f1b; margin-top: 6px">With any picture book bought at Saturday story hour. Good through December 31, 1998.</div></div></div><div style="position: absolute; left: 420px; top: 188px; width: 340px"><div style="border-bottom: 3px solid #b08a45; padding-bottom: 4px;"><div style="display: inline-block; background: #7e1f2d; color: #f8f4ec; font-family: 'Libre Caslon Display', serif; font-size: 36px; line-height: 1; padding: 8px 18px 10px; letter-spacing: 0.005em">Party platters</div></div><div style="margin-top: 18px"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 16px; font-family: 'Libre Caslon Display', serif; font-size: 26px; line-height: 1.15; color: #2b1f1b"><span>Smoked salmon bites</span><span style="color: #7e1f2d">24.00</span></div><div style="font-family: 'Lora', serif; font-size: 20px; line-height: 1.38; color: #2b1f1b; margin-top: 3px">Two dozen cucumber rounds with dill cream cheese, capers and cracked pepper.</div></div><div style="margin-top: 18px; border: 2px solid #7e1f2d; padding: 4px; background: #fffdf8"><img src="assets/era/bookshopcafe/still-platter-9b40da.webp" alt="A book party spread with salmon roe, sliced ham and crudites" style="display: block; width: 328px; height: 197px"></div><div style="font-family: 'Lora', serif; font-style: italic; font-size: 15px; line-height: 1.35; color: #6a5a50; margin-top: 6px">Platters take two days. Roe to finish.</div><div style="height: 2px; background: #b08a45; margin: 14px 0 14px"></div><div style="font-family: 'Lora', serif; font-weight: 700; font-size: 18px; letter-spacing: 0.22em; color: #7e1f2d; text-transform: uppercase; line-height: 1;">Welcome, neighbour</div><div style="font-family: 'Lora', serif; font-size: 17px; line-height: 1.45; color: #2b1f1b; margin-top: 8px">Take any book off the shelf, bring it to your table and stay as long as you like. We will keep the coffee coming. Dogs wait outside, except Brinkley.</div><div style="font-family: 'Mrs Saint Delafield', cursive; font-size: 50px; line-height: 1; color: #2b1f1b; margin-top: 16px">Joe Fox</div><div style="position: relative; margin: 4px 0 0 4px; width: 332px; height: 96px; background: #2b1f1b; transform: rotate(-2.5deg); box-shadow: 0 2px 6px rgba(40,25,20,0.3)"><div style="position: absolute; left: 8px; top: 8px; width: 316px; height: 80px; border: 1px solid #b08a45; box-sizing: border-box"></div><div style="position: absolute; left: 22px; top: 18px; font-family: 'Lora', serif; font-weight: 700; font-size: 14px; letter-spacing: 0.2em; color: #b08a45">STAFF PICK</div><div style="position: absolute; left: 22px; top: 38px; font-family: 'Libre Caslon Display', serif; font-size: 26px; line-height: 1; color: #f8f4ec">Pride and Prejudice</div><div style="position: absolute; left: 22px; top: 66px; font-family: 'Lora', serif; font-style: italic; font-size: 15px; color: #e3d6c0">Jane Austen. Paperback, 5.95</div><div style="position: absolute; left: 286px; top: 22px; width: 18px; height: 52px; background: #7e1f2d"></div></div></div><div style="position: absolute; left: 56px; top: 984px; width: 704px; height: 1px; background: #2b1f1b; opacity: 0.45"></div><div style="position: absolute; left: 56px; top: 992px; width: 704px; display: flex; justify-content: space-between; font-family: 'Lora', serif; font-size: 15px; color: #6a5a50"><span>Fox &amp; Sons Books, Broadway. School supplies on the lower level.</span><span>Prices subject to change. You&#39;ve got mail. FB-152</span></div><img src="assets/era/bookshopcafe/wear-back-fc25e1.webp" alt="" aria-hidden="true" style="position: absolute; left: 0; top: 0; width: 816px; height: 1056px; display: block"></div>`
  ],fmtBookshopCafe.sheet);
}
